/**
 * Vue と Vite の SPA のための Vite のプラグイン。
 * 開発のときにエージェントの経路を手元の Flue の開発のサーバーへ中継し、
 * ページに会話の URL の接頭辞を埋め込む。許可の関数は Flue の開発のサーバーの中で動く
 */
import { resolve } from "node:path";
import type { Plugin } from "vite";
import {
	clientConfigScript,
	resolveAgentDevUrl,
	resolveAgentRoutes,
} from "./frontend-config";

export type RouarViteOptions = {
	/** エージェントの経路の接頭辞。省くと rouar.json の agent.routes を読み、なければ /agents */
	agentRoutes?: string[];
	/** 中継先。省くと ROUAR_AGENT_DEV_URL、なければ http://localhost:5173 */
	target?: string;
};

function escapeRegExp(value: string): string {
	return value.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

/** 接頭辞と、その下のパスだけに当てる。/agents は /agents-old に当てない */
export function proxyKey(route: string): string {
	return `^${escapeRegExp(route)}(?:[/?]|$)`;
}

export function rouar(options: RouarViteOptions = {}): Plugin {
	let routes: string[] = [];
	return {
		name: "rouar",
		config(config, env) {
			routes = resolveAgentRoutes(
				resolve(config.root ?? process.cwd()),
				options.agentRoutes,
			);
			if (env.command !== "serve") return;
			const target = options.target ?? resolveAgentDevUrl();
			return {
				server: {
					proxy: Object.fromEntries(
						routes.map((route) => [
							proxyKey(route),
							// Host を書き換えないので、Flue が返す streamUrl もこのサーバーのオリジンになる
							{ target, changeOrigin: false, ws: false },
						]),
					),
				},
			};
		},
		transformIndexHtml() {
			const route = routes[0];
			if (!route) return;
			return [
				{
					tag: "script",
					children: clientConfigScript(route),
					injectTo: "head-prepend",
				},
			];
		},
	};
}

export default rouar;
